package edu.exam;
import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import jakarta.servlet.http.*;import java.util.*;
@RestControllerAdvice public class Errors {
 @ExceptionHandler(Exception.class) ResponseEntity<?> handle(Exception e,HttpServletRequest r){int s=500;String m="Unable to complete request";Map<String,String> fields=new HashMap<>();if(e instanceof Failure f){s=f.status;m=f.getMessage();}else if(e instanceof org.springframework.web.bind.MethodArgumentNotValidException v){s=400;m="Check the highlighted fields";v.getBindingResult().getFieldErrors().forEach(f->fields.put(f.getField(),f.getDefaultMessage()));}else if(e instanceof org.springframework.dao.DataIntegrityViolationException || e instanceof jakarta.persistence.PersistenceException){s=409;m="Duplicate value or related historical records prevent this change";}else if(e instanceof IllegalArgumentException || e instanceof org.springframework.http.converter.HttpMessageNotReadableException){s=400;m="Invalid request values";}return ResponseEntity.status(s).body(Map.of("timestamp",java.time.Instant.now().toString(),"status",s,"error",HttpStatus.valueOf(s).name(),"message",m,"path",r.getRequestURI(),"fieldErrors",fields));}
}
